-- KTC MÀI STANDARD DATA — 2026-09-03
-- Nguồn: bảng chuẩn Mài người dùng cung cấp
-- Quy tắc: mỗi khoảng/lần lấy MAX; cộng tất cả khoảng/lần; năng suất = 3600 / tổng giây.
-- Chỉ cập nhật các dòng nguồn đủ dữ liệu; các dòng REVIEW không bị đụng tới.
-- Lịch sử: đóng định mức active cũ tại 2026-09-02, tạo version mới từ 2026-09-03.

START TRANSACTION;

-- Tạo bảng tạm chứa dữ liệu chuẩn mới.
DROP TEMPORARY TABLE IF EXISTS tmp_mai_standard_20260903;
CREATE TEMPORARY TABLE tmp_mai_standard_20260903 (
  product_code VARCHAR(180) NOT NULL,
  machine_id BIGINT NOT NULL,
  standard_time_seconds DECIMAL(18,6) NOT NULL,
  calculated_output_per_hour DECIMAL(18,6) NOT NULL,
  source_row_number INT NULL,
  PRIMARY KEY (product_code, machine_id)
);


-- Kiểm tra process MÀI và máy thuộc process MÀI.
SELECT p.id AS process_id, p.process_code, COUNT(*) AS cnt
FROM processes p WHERE p.id=2 GROUP BY p.id,p.process_code;

-- Đóng các version MÀI cũ tương ứng với đúng Mã SP + máy.
UPDATE product_machine_standards pms
JOIN tmp_mai_standard_20260903 t
  ON t.product_code=pms.product_code AND t.machine_id=pms.machine_id
SET pms.effective_to='2026-09-02', pms.is_active=0
WHERE pms.process_id=2 AND pms.is_active=1
  AND (pms.effective_from IS NULL OR pms.effective_from < '2026-09-03');

-- Thêm version chuẩn mới từ 2026-09-03.
-- Idempotent: nếu migration đã chạy rồi thì không tạo duplicate active version.
 calculated_output_per_hour, source_name, source_row_number, effective_from, effective_to, is_active)
SELECT
  2, t.product_code, t.machine_id, t.calculated_output_per_hour,
  t.standard_time_seconds, t.calculated_output_per_hour,
  'KTC_MAI_CHUAN_20260903', t.source_row_number, '2026-09-03', NULL, 1
FROM tmp_mai_standard_20260903 t
WHERE NOT EXISTS (
  SELECT 1
  FROM product_machine_standards pms
  WHERE pms.process_id=2
    AND pms.product_code=t.product_code
    AND pms.machine_id=t.machine_id
    AND pms.effective_from='2026-09-03'
    AND pms.is_active=1
    AND pms.source_name='KTC_MAI_CHUAN_20260903'
);

-- VALIDATION: không có duplicate active cùng Mã SP + máy.
SELECT product_code, machine_id, COUNT(*) AS active_versions
FROM product_machine_standards
WHERE process_id=2 AND is_active=1
GROUP BY product_code, machine_id
HAVING COUNT(*) > 1;

-- VALIDATION: thời gian/năng suất phải khớp 3600 / thời gian.
SELECT id, product_code, machine_id, standard_time_seconds, calculated_output_per_hour
FROM product_machine_standards
WHERE process_id=2 AND is_active=1
  AND (standard_time_seconds <= 0
       OR ABS(calculated_output_per_hour - (3600 / standard_time_seconds)) > 0.000001);

-- Xem các version mới vừa nạp.
SELECT pms.id, pms.product_code, m.machine_code,
       pms.standard_time_seconds, pms.calculated_output_per_hour,
       pms.effective_from, pms.effective_to, pms.is_active
FROM product_machine_standards pms
JOIN machines m ON m.id=pms.machine_id
WHERE pms.process_id=2 AND pms.source_name='KTC_MAI_CHUAN_20260903'
ORDER BY pms.product_code, CAST(m.machine_code AS UNSIGNED);

COMMIT;

-- Nếu validation phía trên trả về dòng lỗi, KHÔNG COMMIT.
-- Trong trường hợp chạy thủ công từng bước, có thể dùng ROLLBACK trước COMMIT.